// app/todos/actions.ts —— Server Action（只能在服务端执行）
'use server'

import { revalidatePath } from 'next/cache'
import { z } from 'zod'
import { db } from '@/lib/db'
import { getCurrentUser } from '@/lib/auth'

// 1. 用 zod 定义并校验入参，避免非法数据进入数据库
const TodoSchema = z.object({
  title: z.string().min(1, '标题不能为空').max(100),
})

export type ActionResult =
  | { ok: true; id: string }
  | { ok: false; error: string }

export async function createTodo(
  _prev: ActionResult | null,
  formData: FormData,
): Promise<ActionResult> {
  // 2. 鉴权永远在服务端再做一次，绝不信任客户端传来的 userId
  const user = await getCurrentUser()
  if (!user) return { ok: false, error: '请先登录' }

  const parsed = TodoSchema.safeParse({
    title: formData.get('title'),
  })
  if (!parsed.success) {
    // 3. 业务错误通过返回值传递，而不是 throw
    return { ok: false, error: parsed.error.errors[0].message }
  }

  const todo = await db.todo.create({
    data: { title: parsed.data.title, userId: user.id },
  })

  // 4. 让受影响的路由重新渲染，缓存自动失效
  revalidatePath('/todos')
  return { ok: true, id: todo.id }
}

