// app/todos/todo-form.tsx —— 客户端表单：useActionState + useFormStatus
'use client'

import { useActionState, useFormStatus } from 'react'
import { createTodo, type ActionResult } from './actions'

// 子组件里用 useFormStatus 读取父级 <form> 的提交状态
function SubmitButton() {
  const { pending } = useFormStatus()
  return (
    <button
      type="submit"
      disabled={pending}
      className="rounded bg-blue-600 px-4 py-2 text-white disabled:opacity-50"
    >
      {pending ? '提交中…' : '添加待办'}
    </button>
  )
}

export function TodoForm() {
  // useActionState 把 Server Action 包装成 [state, formAction]，可拿到上一次结果
  const [state, formAction] = useActionState<ActionResult | null, FormData>(
    createTodo,
    null,
  )

  return (
    <form action={formAction} className="flex gap-2">
      <input
        name="title"
        placeholder="想做点什么？"
        className="flex-1 rounded border px-3 py-2"
        required
      />
      <SubmitButton />
      {state && !state.ok && (
        <p className="text-sm text-red-600">{state.error}</p>
      )}
    </form>
  )
}

