// 乐观更新示例：勾选 Todo 时先变 UI，再等服务端结果
'use client'

import { useOptimistic, useTransition } from 'react'
import { toggleTodo } from './actions'

export function TodoItem({ id, title, done }: {
  id: string; title: string; done: boolean
}) {
  // useOptimistic 的值只在「pending 期间」覆盖真实值，结束后自动恢复
  const [optimisticDone, setOptimisticDone] = useOptimistic(done)
  const [isPending, startTransition] = useTransition()

  return (
    <label className="flex items-center gap-2 opacity-100">
      <input
        type="checkbox"
        checked={optimisticDone}
        disabled={isPending}
        onChange={() =>
          startTransition(async () => {
            setOptimisticDone(!optimisticDone) // 1) 立即渲染乐观状态
            await toggleTodo(id)               // 2) 真正提交到服务端
            // 3) action 完成后，乐观值自动被真实值替换；失败则自动回滚
          })
        }
      />
      <span className={optimisticDone ? 'line-through text-gray-400' : ''}>
        {title}
      </span>
    </label>
  )
}

